import { extractiveSummary, rouge, wordCount, MAX_CHARS } from './engine.js';
const $ = id => document.getElementById(id);
const isGitHubPages = location.hostname.endsWith('.github.io');
const samples = {
  education: { text:'Một trường đại học tại Thành phố Hồ Chí Minh triển khai thư viện số nhằm hỗ trợ sinh viên tự học và nghiên cứu. Hệ thống cho phép tra cứu giáo trình, bài báo khoa học và tài liệu tham khảo bằng tiếng Việt lẫn tiếng Anh. Sinh viên có thể truy cập bằng tài khoản của trường từ máy tính hoặc điện thoại.\n\nTheo đại diện thư viện, việc số hóa tài liệu giúp người học tiết kiệm thời gian tìm kiếm và giảm phụ thuộc vào sách in. Nhà trường tổ chức các buổi hướng dẫn để sinh viên biết cách đánh giá nguồn tin và trích dẫn tài liệu. Các giảng viên cũng được khuyến khích bổ sung học liệu do mình biên soạn vào hệ thống.\n\nTrong giai đoạn đầu, thư viện ưu tiên các môn học đại cương và tài liệu nghiên cứu phục vụ sinh viên năm cuối. Nhóm phụ trách sẽ thu thập phản hồi để cải thiện công cụ tìm kiếm và bổ sung tính năng hỗ trợ người dùng. Nhà trường cho biết việc mở rộng kho học liệu sẽ đi kèm với kiểm tra bản quyền và chất lượng nội dung.', reference:'Một trường đại học tại Thành phố Hồ Chí Minh triển khai thư viện số, giúp sinh viên truy cập học liệu và tra cứu tài liệu phục vụ tự học, nghiên cứu.' },
  technology: { text:'Một nhóm sinh viên phát triển ứng dụng chuyển giọng nói tiếng Việt thành văn bản để hỗ trợ việc ghi chép bài giảng. Ứng dụng sử dụng mô hình nhận dạng tiếng nói và cho phép người dùng chỉnh sửa nội dung sau khi chuyển đổi. Mục tiêu của nhóm là giúp sinh viên tập trung nghe giảng thay vì phải ghi lại toàn bộ lời nói.\n\nTrong quá trình thử nghiệm, hệ thống nhận dạng tốt hơn khi người nói phát âm rõ và môi trường ít tiếng ồn. Với thuật ngữ chuyên ngành hoặc nhiều người nói cùng lúc, bản ghi vẫn có thể xuất hiện lỗi. Vì vậy, nhóm thiết kế giao diện đánh dấu các đoạn cần người dùng kiểm tra.\n\nỨng dụng hiện được thử nghiệm trong phạm vi một số lớp học. Nhóm phát triển dự kiến bổ sung khả năng tìm kiếm trong bản ghi và liên kết từng đoạn văn bản với thời điểm tương ứng trong âm thanh. Việc ghi âm chỉ được thực hiện khi có sự đồng ý của người tham gia.', reference:'Một nhóm sinh viên phát triển ứng dụng chuyển giọng nói tiếng Việt thành văn bản để hỗ trợ ghi chép bài giảng, với khả năng chỉnh sửa và đánh dấu đoạn cần kiểm tra.' },
  environment: { text:'Một địa phương ven biển triển khai chương trình phục hồi rừng ngập mặn nhằm bảo vệ bờ biển và cải thiện sinh kế cho người dân. Hoạt động tập trung vào việc trồng cây bản địa tại những khu vực bị suy giảm diện tích rừng. Người dân được hướng dẫn lựa chọn vị trí trồng phù hợp với thủy triều và điều kiện đất.\n\nRừng ngập mặn có vai trò giảm tác động của sóng, giữ đất và tạo nơi sinh sống cho nhiều loài thủy sản. Tuy nhiên, cây non dễ bị cuốn trôi nếu trồng không đúng thời điểm. Nhóm phụ trách cho biết chương trình sẽ theo dõi tỷ lệ sống của cây thay vì chỉ thống kê số lượng cây đã trồng.\n\nBên cạnh hoạt động phục hồi rừng, địa phương tổ chức thu gom rác và hướng dẫn các hộ dân nuôi trồng thủy sản theo hướng giảm tác động đến môi trường. Chương trình khuyến khích cộng đồng tham gia giám sát để duy trì diện tích rừng sau khi trồng. Kết quả sẽ được đánh giá định kỳ để điều chỉnh phương pháp triển khai.', reference:'Một địa phương ven biển triển khai phục hồi rừng ngập mặn với sự tham gia của người dân, chú trọng tỷ lệ sống của cây, bảo vệ bờ biển và cải thiện sinh kế.' }
};
let selected='extractive', backend=null, busy=false, lastResults=[], resultSource='', resultReference='';
function setError(message=''){$('error').textContent=message;$('error').hidden=!message;}
function updateCount(){$('input-count').textContent=`${wordCount($('article').value).toLocaleString('vi-VN')} âm tiết · ${$('article').value.length.toLocaleString('vi-VN')} ký tự`;}
function setModel(key){selected=key;document.querySelectorAll('[data-model]').forEach(b=>{const active=b.dataset.model===key;b.classList.toggle('selected',active);b.setAttribute('aria-pressed',String(active));});$('method-notice').textContent= key==='extractive'?'Chế độ thử giao diện: chọn câu có sẵn trong bài. Đây không phải đầu ra của mT5 hoặc ViT5.':backend?.models?.[key]?.available?'Checkpoint đã sẵn sàng. Mô hình đọc tối đa 512 token và sinh tối đa 128 token mới.':`Chưa sẵn sàng: ${backend?.models?.[key]?.reason || 'hãy chạy máy chủ Python và cấu hình checkpoint best/ để sử dụng mô hình này.'}`;}
async function checkBackend(){
  if(!isGitHubPages){
    try{const response=await fetch('/api/status',{signal:AbortSignal.timeout(4000),cache:'no-store'});if(response.ok){const data=await response.json();if(data.service==='vietbrief')backend=data;}}catch{}
  }
  const ready=backend?Object.entries(backend.models).filter(([,m])=>m.available).map(([key])=>key):[];
  $('connection-status').textContent=isGitHubPages?'GitHub Pages · Trích xuất câu':ready.length?`${ready.length} mô hình sẵn sàng · ${backend.device}`:backend?'Máy chủ đã kết nối · Chờ checkpoint':'Chế độ trình duyệt';
  $('compare').disabled=!(backend?.models?.mt5?.available&&backend?.models?.vit5?.available);
  $('compare').title=$('compare').disabled?'Cần checkpoint đã đánh giá của cả hai mô hình':'';
  if(ready.length)setModel(ready.includes('mt5')?'mt5':ready[0]);else setModel(selected);
  if(isGitHubPages){
    $('method-notice').textContent='Bản GitHub Pages tóm tắt bằng trích xuất câu ngay trên trình duyệt. Để dùng mT5/ViT5, mở bản Python trên máy đã có checkpoint.';
    document.querySelectorAll('[data-model]').forEach(button=>{if(button.dataset.model!=='extractive'){button.disabled=true;button.title='Chạy mô hình này trong bản Python trên máy có checkpoint.';}});
  }
  document.querySelectorAll('[data-model-status]').forEach(cell=>{cell.textContent=backend?.models?.[cell.dataset.modelStatus]?.available?'Đã kết nối · run04':isGitHubPages?'Dùng trong bản Python':'Cần checkpoint best/';});
}
function element(tag, className, text){const e=document.createElement(tag);if(className)e.className=className;if(text!==undefined)e.textContent=text;return e;}
function metric(label, value){const e=element('div','metric');e.append(element('strong','',value),document.createTextNode(label));return e;}
function renderResults(results, reference){$('results').replaceChildren();for(const r of results){const card=element('article','result-card');const title=element('div','result-model',r.label);title.append(element('span','',r.model==='extractive'?'TRÍCH XUẤT':`CHECKPOINT FINE-TUNE${r.device?' · '+r.device.toUpperCase():''}`));card.append(title,element('p','summary-text',r.summary));const metrics=element('div','result-metrics');if(r.input_tokens!==null&&r.input_tokens!==undefined){metrics.append(metric('token đầu vào',r.input_tokens.toLocaleString('vi-VN')),metric('token được đọc',String(r.used_tokens)));}else metrics.append(metric('câu được chọn',`${r.sentences_selected} / ${r.sentences_total}`));metrics.append(metric('thời gian xử lý',`${r.seconds.toFixed(2)} s`),metric('độ dài / bài gốc',`${(wordCount(r.summary)/Math.max(wordCount(resultSource),1)*100).toFixed(1)}%`));card.append(metrics);if(reference.trim()){try{const scores=rouge(r.summary,reference);r.rouge=scores;const scoreRow=element('div','result-metrics');scoreRow.style.marginTop='8px';for(const [key,value]of Object.entries(scores))scoreRow.append(metric(key.replace('rouge','ROUGE-'),value.toFixed(2)));card.append(scoreRow);}catch(e){card.append(element('p','notice',e.message));}}for(const warning of r.warnings||[])card.append(element('p','notice',warning));$('results').append(card);}$('result-actions').hidden=false;}
async function run(){if(busy)return;setError();const text=$('article').value;const reference=$('reference').value;if(!text.trim()){setError('Hãy nhập bài báo hoặc chọn một ví dụ để bắt đầu.');$('article').focus();return;}if(text.length>MAX_CHARS){setError('Bài báo vượt 200.000 ký tự. Hãy rút ngắn nội dung.');return;}const models=$('compare').checked?['mt5','vit5']:[selected];if(models.some(key=>key!=='extractive'&&!backend?.models?.[key]?.available)){setError('Mô hình chưa sẵn sàng. Hãy cấu hình checkpoint trong máy chủ Python, hoặc chọn “Trích xuất câu” để thử giao diện.');return;}busy=true;document.querySelectorAll('button,textarea,input,summary').forEach(e=>{e.dataset.wasDisabled=String(e.disabled||false);if('disabled'in e)e.disabled=true;});$('output-panel').setAttribute('aria-busy','true');$('result-actions').hidden=true;$('results').replaceChildren();const loading=element('div','loading');loading.append(element('div','spinner'),element('span','',models[0]==='extractive'?'Đang chọn những câu chứa ý chính…':'Đang nạp checkpoint và sinh tóm tắt. Lần đầu có thể mất vài phút…'));$('results').append(loading);try{const results=[];for(const key of models){let result;if(key==='extractive'){await new Promise(resolve=>setTimeout(resolve,180));const start=performance.now();result=extractiveSummary(text);result.seconds=(performance.now()-start)/1000;}else{const response=await fetch('/api/summarize',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text,model:key}),signal:AbortSignal.timeout(600000)});const data=await response.json();if(!response.ok)throw new Error(data.error||'Không thể sinh tóm tắt.');result=data;}results.push(result);}lastResults=results;resultSource=text;resultReference=reference;renderResults(results,reference);}catch(e){lastResults=[];$('results').replaceChildren(element('div','empty-state','Chưa tạo được tóm tắt. Kiểm tra thông báo bên dưới.'));setError(e.name==='TimeoutError'?'Thời gian chờ đã hết. Máy chủ có thể vẫn đang xử lý; hãy chờ rồi thử lại.':e.message);}finally{busy=false;document.querySelectorAll('[data-was-disabled]').forEach(e=>{if('disabled'in e)e.disabled=e.dataset.wasDisabled==='true';delete e.dataset.wasDisabled;});$('output-panel').setAttribute('aria-busy','false');}}
function exportText(){return lastResults.map(r=>`${r.label}\n${r.summary}\n\nThời gian xử lý: ${r.seconds.toFixed(2)} giây${r.input_tokens!=null?`\nToken đầu vào: ${r.input_tokens} | Token được đọc: ${r.used_tokens}`:''}${r.rouge?'\n'+Object.entries(r.rouge).map(([k,v])=>`${k}: ${v.toFixed(2)}`).join(' | '):''}\n${(r.warnings||[]).join('\n')}`).join('\n\n--------------------\n\n');}
document.querySelectorAll('[data-model]').forEach(b=>b.addEventListener('click',()=>{setModel(b.dataset.model);$('compare').checked=false;setError();}));
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>{const isDemo=b.dataset.view==='demo';$('demo-view').hidden=!isDemo;$('project-view').hidden=isDemo;document.querySelectorAll('.nav-button').forEach(n=>n.classList.toggle('active',n.dataset.view===b.dataset.view));window.scrollTo({top:0,behavior:'smooth'});}));
$('compare').addEventListener('change',()=>{if($('compare').checked){setModel('mt5');$('method-notice').textContent='Chạy mT5 và ViT5 lần lượt trên cùng bài báo với cùng cấu hình sinh; mỗi lần chỉ nạp một mô hình để tiết kiệm bộ nhớ.';}else setModel(selected);});
$('article').addEventListener('input',updateCount);$('summarize').addEventListener('click',run);
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='Enter'&&!$('demo-view').hidden){e.preventDefault();run();}});
document.querySelectorAll('[data-sample]').forEach(b=>b.addEventListener('click',()=>{const sample=samples[b.dataset.sample];$('article').value=sample.text;$('reference').value=sample.reference;updateCount();setError();}));
const initialEmpty=$('results').innerHTML;
$('clear').addEventListener('click',()=>{$('article').value='';$('reference').value='';$('file').value='';lastResults=[];$('results').innerHTML=initialEmpty;$('result-actions').hidden=true;setError();updateCount();$('article').focus();});
$('upload').addEventListener('click',()=>$('file').click());$('file').addEventListener('change',async()=>{const file=$('file').files[0];if(!file)return;try{if(!/\.txt$/i.test(file.name))throw new Error('Hãy chọn tệp .txt mã hóa UTF-8.');if(file.size>800000)throw new Error('Tệp quá lớn; chỉ hỗ trợ tối đa 200.000 ký tự.');const text=await file.text();if(text.length>MAX_CHARS)throw new Error('Tệp vượt 200.000 ký tự.');$('article').value=text;$('reference').value='';updateCount();setError();}catch(e){setError(e.message);}finally{$('file').value='';}});
$('copy').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(exportText());$('copy-status').textContent='Đã sao chép';setTimeout(()=>{$('copy-status').textContent='';},2500);}catch{setError('Trình duyệt không cho phép sao chép. Bạn có thể dùng nút “Tải kết quả”.');}});
$('download').addEventListener('click',()=>{const body=`VIETBRIEF · KẾT QUẢ DEMO\n${new Date().toLocaleString('vi-VN')}\n\n${exportText()}\n\nBÀI BÁO GỐC\n${resultSource}${resultReference?`\n\nTHAM CHIẾU\n${resultReference}`:''}`;const url=URL.createObjectURL(new Blob(['\uFEFF',body],{type:'text/plain;charset=utf-8'}));const link=element('a');link.href=url;link.download='vietbrief-tom-tat.txt';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
checkBackend();
